-- "addons\\sardoncigirtkan\\lua\\sardon_cigirtkan\\cl_2aktarim.lua"
-- Retrieved by https://github.com/lewisclark/glua-steal
-- Sardon Çığırtkan :: istemci — sesin alınması, geçici dosya ve ses kanalları.
--
-- Sunucu MP3'ü parça parça yollar (SardonCigirtkan.Parca). Hepsi gelince data/sardon_cigirtkan/<kimlik>.mp3
-- yazılır ve sound.PlayFile ile açılır (3B: zarfın konumunda; 2B: gönderenin önizlemesi).
-- Sunucu "Unut" deyince kanal durdurulur, dosya silinir. Windows açık dosyayı silmeye izin vermeyebilir;
-- silinemeyen dosya birkaç saniyede bir yeniden denenir, açılışta da klasörde kalan her şey silinir.
-- Yazılı çığırtkan: belge tek pakette gelir (C.yazilar); daktilo sesleri bu dosyaya gömülüdür, açılışta
-- data/sardon_cigirtkan_daktilo/ altına çıkar ve önceden açılmış 3B kanallardan çalınır (C.DaktiloSes).
local C = SardonCigirtkan

C.veri = C.veri or {}           -- [kimlik] = {parca = {}, n, gelen, boy, hazir, dosya, k2, k3, ...}
C.silinecek = C.silinecek or {} -- [dosya] = şu zamandan sonra sil

local KLASOR = "sardon_cigirtkan"
file.CreateDir(KLASOR)

-- Önceki oturumdan kalanlar
if not C.acilisTemiz then
     C.acilisTemiz = true
     for _, f in ipairs(file.Find(KLASOR .. "/*", "DATA") or {}) do
          file.Delete(KLASOR .. "/" .. f)
     end
end

net.Receive("SardonCigirtkan.Parca", function()
     local id = net.ReadUInt(32)
     local i = net.ReadUInt(8)
     local n = net.ReadUInt(8)
     local boy = net.ReadUInt(24)
     local d = net.ReadData(net.ReadUInt(16))

     local v = C.veri[id]
     if not v or v.n ~= n or v.boy ~= boy then
          v = {parca = {}, n = n, gelen = 0, boy = boy}
          C.veri[id] = v
     end
     if v.hazir or v.parca[i] then return end

     v.parca[i] = d
     v.gelen = v.gelen + 1
     if v.gelen < n then return end

     local veri = table.concat(v.parca)
     v.parca = nil
     if #veri ~= boy then
          C.veri[id] = nil
          return
     end
     v.dosya = KLASOR .. "/" .. id .. ".mp3"
     file.Write(v.dosya, veri)
     v.hazir = file.Exists(v.dosya, "DATA")
end)

-- Ses verisi tamamen geldi mi
function C.Hazir(id)
     local v = C.veri[id]
     return v ~= nil and v.hazir == true
end

-- Kanal (yüklüyse). uc = true: 3B. İlk çağrıda yüklemeyi başlatır, hazır olana dek nil döner.
function C.Kanal(id, uc)
     local v = C.veri[id]
     if not v or not v.hazir then return nil end
     local k = uc and "k3" or "k2"
     local ch = v[k]
     if ch and ch:IsValid() then return ch end
     if v[k .. "y"] or (v[k .. "h"] or 0) >= 2 then return nil end

     v[k .. "y"] = true
     sound.PlayFile("data/" .. v.dosya, uc and "3d noplay" or "noplay", function(kanal, kod, ad)
          v[k .. "y"] = nil
          if C.veri[id] ~= v then
               if IsValid(kanal) then kanal:Stop() end
               return
          end
          if IsValid(kanal) then
               v[k] = kanal
          else
               v[k .. "h"] = (v[k .. "h"] or 0) + 1
               MsgN("[Cigirtkan] ses acilamadi (" .. tostring(kod) .. " " .. tostring(ad) .. ")")
          end
     end)
     return nil
end

function C.Unut(id)
     C.yazilar[id] = nil
     local v = C.veri[id]
     if not v then return end
     C.veri[id] = nil
     for _, k in ipairs({"k2", "k3"}) do
          if v[k] and v[k]:IsValid() then v[k]:Stop() end
          v[k] = nil
     end
     if v.dosya then C.silinecek[v.dosya] = CurTime() + 1 end
     hook.Run("SardonCigirtkanUnut", id)
end

net.Receive("SardonCigirtkan.Unut", function()
     C.Unut(net.ReadUInt(32))
end)

timer.Create("SardonCigirtkan.Sil", 4, 0, function()
     local simdi = CurTime()
     for f, t in pairs(C.silinecek) do
          if simdi >= t then
               file.Delete(f)
               if not file.Exists(f, "DATA") then C.silinecek[f] = nil end
          end
     end
end)

----------------------------------------------------------------------------------------
-- Yazılı çığırtkan: belge ve daktilo sesleri
----------------------------------------------------------------------------------------
C.yazilar = C.yazilar or {}     -- [kimlik] = {yazi, belge = C.DaktiloBelge(yazi)}

-- DAKTILO_SES_BASLA (tools/daktilo_ses_uret.py üretir; elle düzenleme)
local DAKTILO_SES = {
     tus1 = "",
     tus2 = "",
     tus3 = "",
     tus4 = "",
     bosluk = "",
     zil = "",
     satir = "",
     besleme = "",
     damga = "",
}
-- DAKTILO_SES_BITTI

local DKLASOR = "sardon_cigirtkan_daktilo"
local SESLER = {harf = {"tus1", "tus2", "tus3", "tus4"}, bosluk = {"bosluk"}, zil = {"zil"}, satir = {"satir"}, besleme = {"besleme"}, damga = {"damga"}}
local HAVUZ = {tus1 = 2, tus2 = 2, tus3 = 2, tus4 = 2, bosluk = 2, zil = 1, satir = 1, besleme = 1, damga = 1}
-- Ses dosyası açılamazsa en yakın oyun sesleri (HL2'de daktilo yok)
local YEDEK = {
     harf = "buttons/lightswitch2.wav", bosluk = "buttons/lightswitch2.wav", zil = "plats/elevbell1.wav",
     satir = "ambient/machines/keyboard7_clicks_enter.wav", besleme = "ambient/machines/keyboard5_clicks.wav",
     damga = "physics/cardboard/cardboard_box_impact_hard1.wav",
}

C.daktiloKanal = C.daktiloKanal or {}   -- [ses adı] = {kanal, ...}
local sira = {}

local function SesleriYaz()
     file.CreateDir(DKLASOR)
     for ad, b64 in pairs(DAKTILO_SES) do
          local yol = DKLASOR .. "/" .. ad .. ".mp3"
          local veri = util.Base64Decode(b64)
          if veri and (not file.Exists(yol, "DATA") or file.Size(yol, "DATA") ~= #veri) then file.Write(yol, veri) end
     end
end
SesleriYaz()

-- Kanallar ilk yazılı zarf geldiğinde açılır (çoğu oyuncu hiç almaz)
function C.DaktiloHazirla()
     if C.daktiloKanalAcildi then return end
     C.daktiloKanalAcildi = true
     for ad, n in pairs(HAVUZ) do
          C.daktiloKanal[ad] = C.daktiloKanal[ad] or {}
          for _ = 1, n do
               sound.PlayFile("data/" .. DKLASOR .. "/" .. ad .. ".mp3", "3d noplay", function(k)
                    if IsValid(k) then
                         k:Set3DFadeDistance(220, 100000)
                         table.insert(C.daktiloKanal[ad], k)
                    end
               end)
          end
     end
end

-- tur: harf | bosluk | zil | satir | besleme | damga. ses: seviye (uzaklık / duvar çarpanı çağırandan), hiz: perde
function C.DaktiloSes(tur, pos, ses, hiz)
     local adlar = SESLER[tur]
     if not adlar then return end
     C.DaktiloHazirla()
     local ad = adlar[math.random(1, #adlar)]
     local liste = C.daktiloKanal[ad]
     local k
     if liste and #liste > 0 then
          sira[ad] = (sira[ad] or 0) % #liste + 1
          k = liste[sira[ad]]
     end
     if IsValid(k) then
          k:SetPos(pos)
          k:SetVolume(ses)
          k:SetPlaybackRate(hiz or 1)
          k:SetTime(0)
          k:Play()
     else
          sound.Play(YEDEK[tur], pos, 66, math.Clamp(math.floor(100 * (hiz or 1)) + (tur == "harf" and 25 or 0), 50, 200), math.min(1, ses))
     end
end

net.Receive("SardonCigirtkan.Yazi", function()
     local id = net.ReadUInt(32)
     local yazi = C.YaziTemizle(net.ReadTable())
     C.yazilar[id] = {yazi = yazi, belge = C.DaktiloBelge(yazi)}
     C.DaktiloHazirla()
end)
